/**
 * 负责独立审核贵族契约与秘身挡伤证据，并返回贵族审计结果。输入为归档配置、决定、事实与 checkpoint；
 * 输出为独立重建的审计结果或原拒绝，原纯数据推导、迭代与第一失败顺序保持。
 * 稳定枚举来自中立契约，不通过 barrel 加载 World／生产伤害；不读取或写入真实库存。
 * 结构读器仅确认数据；既有算法只消费归档，不授予游戏权限，也不替换原拒绝政策。
 */
import { createMistSheriffEvidence } from "../mist-raven/sheriff-evidence";
import { isNobleSecretBodyPreset } from "../../board-support";
import {
  NOBLE_SECRET_BODY_EVENT_TYPES,
  readNobleSecretBodyFact,
} from "@ai-werewolf-arena/game-contract/facts/noble-secret-body";
import { Role, Camp, Phase } from "@ai-werewolf-arena/game-contract";
import type { RecordedCheckpoint, RecordedDecision, ReproductionRecord } from "../../../recording/reproduction";
import type { RecordedNobleBodyState } from "../../../recording/checkpoint/noble-body-format";
import { sanitizeSpeechText } from "../../../utils/speech_text";
export function nobleRecordCheck(v: unknown): asserts v {
  if (!v) throw Error("reproduction_noble_secret_body_invalid");
}
export function nobleRecordEqual(a: unknown, b: unknown): boolean {
  const sort = (v: unknown): unknown =>
    Array.isArray(v)
      ? v.map(sort)
      : v && typeof v === "object"
        ? Object.fromEntries(
            Object.entries(v)
              .filter(([, x]) => x !== undefined)
              .sort(([a], [b]) => a.localeCompare(b))
              .map(([k, x]) => [k, sort(x)]),
          )
        : v;
  return JSON.stringify(sort(a)) === JSON.stringify(sort(b));
}
const check: (v: unknown) => asserts v = nobleRecordCheck,
  equal = nobleRecordEqual,
  policy = "awa_noble_secret_body_v1";
type Sources = Record<string, string[]>;
export interface NobleNightAudit {
  day: number;
  start: number[];
  requiresBody: boolean;
  requiresNoble: boolean;
  knife: number | null;
  heal: number | null;
  poison: number | null;
  hunt: { day: number; targetId: number | null } | null;
  huntDamage: { targetId: number; cause: string } | null;
  clear: Record<string, unknown> | null;
  beforeBody: Sources;
  blocked: { targetId: number; cause: string } | null;
  final: Sources;
}
/** 交给猎魔人核验的独立审计数据；at 按原 checkpoint identity 取历史副本，nights 保原 Map 写性。 */
export interface NobleRecordAudit {
  at: (cp: RecordedCheckpoint) => RecordedNobleBodyState;
  nights: Map<number, NobleNightAudit>;
}
/** 对归档独立推导；不用运行时 owner、状态迁移、伤害折叠器、
 * World 权限选择器或生产可见性实现生成校验预期。 */
export function validateNobleSecretBodyRecord(record: ReproductionRecord): NobleRecordAudit | null {
  const board = record.metadata.normalizedBoard,
    owns = !!board.nobleSecretBody;
  if (!owns) {
    check(
      !board.nightNoble &&
        !board.awakenedIdiot &&
        !board.roleSetups.some((r) => [Role.NightNoble, Role.AwakenedIdiot].includes(r.role)) &&
        !record.operations.some(
          (o) =>
            o.op.startsWith("noble_") ||
            o.op.startsWith("secret_body_") ||
            (!board.fragrantPairSeer && !board.animalDream && o.event_count !== undefined),
        ) &&
        !record.decisions.some(
          (d) =>
            (!board.fragrantPairSeer && !board.animalDream && d.openedAtEventCount !== undefined) ||
            ["secret_body", "night_noble", "awakened_idiot_reveal_speech"].includes(d.stage) ||
            d.request.allowedTools.some((t) =>
              ["choose_servant", "protect_secret_body"].includes(t),
            ),
        ) &&
        !record.checkpoints.some((cp) =>
          cp.players.some(
            (p) =>
              Object.hasOwn(p.privateState, "noble") || Object.hasOwn(p.privateState, "secretBody"),
          ),
        ),
    );
    check(
      !record.checkpoints.some(
        (cp) =>
          cp.nobleBody ||
          (!board.fragrantPairSeer &&
            !board.animalDream &&
            (cp.operationCount !== undefined ||
              cp.settlementCount !== undefined ||
              cp.decisionCount !== undefined)),
      ) &&
        !record.events.some((e) =>
          (NOBLE_SECRET_BODY_EVENT_TYPES as readonly string[]).includes(e.type),
        ),
    );
    return null;
  }
  check(isNobleSecretBodyPreset(board) && !record.metadata.initialDeal);
  const roster = new Map(record.metadata.players.map((p) => [p.id, p])),
    roleId = (r: Role) => {
      const found = [...roster.values()].find((p) => p.role === r);
      check(found);
      return found.id;
    },
    nobleId = roleId(Role.NightNoble),
    bodyId = roleId(Role.AwakenedIdiot),
    witchId = roleId(Role.Witch),
    demonId = roleId(Role.DemonHunter),
    seerId = roleId(Role.Seer);
  check(
    record.metadata.players.length === 12 &&
      roster.size === 12 &&
      equal(
        [...roster.keys()],
        Array.from({ length: 12 }, (_, i) => i + 1),
      ) &&
      board.roleSetups.every(
        (row) => [...roster.values()].filter((p) => p.role === row.role).length === row.count,
      ),
  );
  for (const p of roster.values())
    check(p.camp === ([Role.Wolf, Role.NightNoble].includes(p.role) ? Camp.Wolf : Camp.Good));
  const state: RecordedNobleBodyState = {
    nobleId,
    bodyId,
    noble: {
      policy,
      wolfActionPolicy: board.nightNoble!.wolfActionPolicy,
      lastChoice: null,
      contracts: [],
    },
    body: {
      policy,
      protectionRepeatPolicy: board.awakenedIdiot!.protectionRepeatPolicy,
      lastChoice: null,
      body: { kind: "intact" },
    },
    knowledge: {
      noble: {
        wolfActionPolicy: board.nightNoble!.wolfActionPolicy,
        lastNotifiedNight: 0,
        lastChoice: null,
        contracts: [],
      },
      body: {
        protectionRepeatPolicy: board.awakenedIdiot!.protectionRepeatPolicy,
        lastNotifiedNight: 0,
        lastChoice: null,
        resource: "intact",
        publicRevealDay: null,
      },
    },
    notices: [],
    nights: [],
  };
  const alive = new Set(roster.keys()),
    marks = new Map([...roster.keys()].map((id) => [id, [] as string[]])),
    announcedDead = new Set<number>(),
    nights = new Map<number, NobleNightAudit>(),
    snapshots = new Map<RecordedCheckpoint, RecordedNobleBodyState>(),
    votes = new Map([...roster.keys()].map((id) => [id, { weight: 1, canVote: true }])),
    badges = new Map(
      [...roster.keys()].map(
        (id) => [id, { isSheriff: false, destroyed: false, voteWeight: 1.5 }] as const,
      ),
    );
  const election = createMistSheriffEvidence(record);
  let exileExpected: number | null = null,
    votedOut: number | null = null,
    exileCandidates: number[] | null = null,
    exileRound = 1,
    pendingBlast: number | null = null;
  let day = 1,
    phase: Phase = Phase.Night,
    sheriff: number | null = null,
    healStock = 1,
    poisonStock = 1;
  const rows = (d: number, stage: string, actor?: number) =>
    record.decisions.filter(
      (q) => q.day === d && q.stage === stage && (actor === undefined || q.actorId === actor),
    );
  const action = (d: number, stage: string, actor: number) => {
    const ds = rows(d, stage, actor);
    check(ds.length === 1 && ds[0]!.outcome.kind === "action");
    return ds[0]!.outcome.action;
  };
  const pending = () => state.noble.contracts.find((c) => c.status.kind === "pending");
  const night = () => state.nights.find((n) => n.day === day)!;
  const begin = () => {
    if (nights.has(day)) return;
    check(
      ![...state.nights].some((n) => n.day >= day) &&
        !state.noble.contracts.some((c) => c.status.kind === "pending" && c.expiresNight < day),
    );
    nights.set(day, {
      day,
      start: [...alive].sort((a, b) => a - b),
      requiresBody: alive.has(bodyId) && state.body.body.kind === "intact",
      requiresNoble: day >= 2 && alive.has(nobleId) && !pending(),
      knife: null,
      heal: null,
      poison: null,
      hunt: null,
      huntDamage: null,
      clear: null,
      beforeBody: {},
      blocked: null,
      final: {},
    });
    state.nights.push({
      day,
      status: "open",
      bodyChosen: false,
      nobleChosen: false,
      expiryProcessed: false,
      bodyResolved: false,
      revealOpened: false,
      revealCompleted: false,
    });
  };
  const makeClosed = (
    c: RecordedNobleBodyState["noble"]["contracts"][number],
    status: "cleared" | "expired" | "target_dead",
  ) => ({
    policy,
    actorId: nobleId,
    day,
    contractId: c.id,
    targetId: c.targetId,
    createdNight: c.createdNight,
    expiresNight: c.expiresNight,
    status,
    ...(status === "expired" ? { proposedCause: "servant_expiry" } : {}),
  });
  const derive = (n: NobleNightAudit) => {
    const add = (id: number, cause: string) => {
      check(alive.has(id));
      const list = (n.beforeBody[id] ??= []);
      check(!list.includes(cause));
      list.push(cause);
    };
    n.knife = deriveKnife(n);
    if (n.start.includes(witchId)) {
      const a = action(day, "witch", witchId);
      check(a?.name === "use_potion");
      if (a.args.potion_type === "heal") {
        check(healStock === 1 && a.args.target_id === n.knife && a.args.target_id !== witchId);
        healStock = 0;
        n.heal = a.args.target_id;
      } else if (a.args.potion_type === "poison") {
        check(poisonStock === 1 && n.start.includes(a.args.target_id));
        poisonStock = 0;
        n.poison = a.args.target_id;
      } else check(a.args.potion_type === "none");
    } else check(rows(day, "witch").length === 0);
    if (day >= 2 && n.start.includes(demonId)) {
      const a = action(day, "demon_hunter", demonId);
      check(
        a?.name === "demon_hunt" &&
          typeof a.args.abstain === "boolean" &&
          (a.args.abstain
            ? a.args.target_id === null
            : typeof a.args.target_id === "number" &&
              a.args.target_id !== demonId &&
              n.start.includes(a.args.target_id)),
      );
      n.hunt = { day, targetId: a.args.target_id };
    } else check(rows(day, "demon_hunter").length === 0);
    const c = pending(),
      h = n.hunt?.targetId;
    if (h !== null && h !== undefined) {
      if (c && c.targetId === h) {
        n.clear = makeClosed(c, "cleared");
      } else
        n.huntDamage = {
          targetId: roster.get(h)!.camp === Camp.Wolf ? h : demonId,
          cause: roster.get(h)!.camp === Camp.Wolf ? "demon_hunt" : "demon_hunt_backlash",
        };
    }
    if (n.poison !== null && n.poison !== demonId) add(n.poison, "poison");
    if (n.knife !== null && n.heal !== n.knife) add(n.knife, "wolf_kill");
    if (n.huntDamage) add(n.huntDamage.targetId, n.huntDamage.cause);
    if (c && !n.clear && c.expiresNight === day) add(c.targetId, "servant_expiry");
  };
  const deriveKnife = (n: NobleNightAudit): number | null => {
    const wolves = n.start.filter((id) => roster.get(id)!.camp === Camp.Wolf),
      vs = rows(day, "wolf_vote"),
      tally = new Map<number, number>();
    check(
      equal(
        vs.map((d) => d.actorId).sort((a, b) => a - b),
        wolves,
      ),
    );
    for (const d of vs) {
      check(d.outcome.kind === "action" && d.outcome.action?.name === "kill_vote");
      const a = d.outcome.action.args;
      check(typeof a.abstain === "boolean");
      if (!a.abstain) {
        check(
          typeof a.target_id === "number" &&
            n.start.includes(a.target_id) &&
            !(
              board.nightNoble!.wolfActionPolicy === "no_blast_no_self_knife" &&
              a.target_id === nobleId
            ),
        );
        tally.set(a.target_id, (tally.get(a.target_id) ?? 0) + 1);
      }
    }
    return [...tally].sort(([a, x], [b, y]) => y - x || a - b)[0]?.[0] ?? null;
  };
  const prepared = new Set<number>(),
    closures = new Set<string>(),
    sourceCommits = new Set<number>();
  const prepare = () => {
    begin();
    if (!prepared.has(day)) {
      derive(nights.get(day)!);
      prepared.add(day);
    }
    return nights.get(day)!;
  };
  const close = (payload: Record<string, unknown>) => {
    const c = state.noble.contracts.find((c) => c.id === payload.contractId);
    check(
      c && payload.actorId === nobleId && !closures.has(c.id) && payload.targetId === c.targetId,
    );
    if (payload.status === "target_dead") check(!alive.has(c.targetId));
    else {
      check(eventSeen.has(`native/${day}`));
      const n = prepare();
      if (payload.status === "cleared") check(equal(payload, n.clear));
      else check(payload.status === "expired" && !n.clear && c.expiresNight === day);
    }
    check(equal(payload, makeClosed(c, payload.status as "cleared" | "expired" | "target_dead")));
    if (c.status.kind === "pending")
      c.status = { kind: payload.status as "cleared" | "expired" | "target_dead", day };
    else check(c.status.kind === payload.status && c.status.day === day);
    closures.add(c.id);
  };
  const sources = () => {
    check(eventSeen.has(`native/${day}`));
    const n = prepare();
    check(!sourceCommits.has(day));
    const current = night();
    check(current && current.status === "open");
    const bodyRequired = n.start.includes(bodyId) && state.body.body.kind === "intact";
    check(!bodyRequired || current.bodyChosen);
    check(!n.requiresNoble || current.nobleChosen);
    const expected = structuredClone(n.beforeBody),
      priority = [
        "wolf_kill",
        "poison",
        "demon_hunt",
        "demon_hunt_backlash",
        "servant_expiry",
      ] as const;
    if (current.bodyChosen && state.body.body.kind === "intact") {
      const selected = state.body.lastChoice!.targetId ?? bodyId,
        target = expected[selected]?.length ? selected : bodyId,
        cause = priority.find((c) => expected[target]?.includes(c));
      if (cause) {
        n.blocked = { targetId: target, cause };
        expected[target] = expected[target]!.filter((c) => c !== cause);
        if (!expected[target]!.length) delete expected[target];
        state.body.body = {
          kind: "night_spent",
          day,
          targetId: target,
          cause: cause as "wolf_kill",
        };
      }
    }
    n.final = expected;
    current.status = "normal";
    current.expiryProcessed = true;
    current.bodyResolved = true;
    sourceCommits.add(day);
    return n;
  };
  const eventSeen = new Set<string>();
  const mark = (key: string) => {
    check(!eventSeen.has(key));
    eventSeen.add(key);
  };
  let initialInfoSeen = false;
  const seenNotice = new Set<string>(),
    observed = new Map(
      [...roster.keys()].map((id) => [
        id,
        [] as Array<{ seq: number; type: string; payload: Record<string, unknown> }>,
      ]),
    );
  const publicTypes = new Set([
    "phase_changed",
    "day_speech",
    "night_resolved",
    "vote_summary",
    "voted_out",
    "game_over",
    "wolf_self_destruct",
    "last_words_granted",
    "last_words_spoken",
    "sheriff_nomination_summary",
    "sheriff_withdraw_summary",
    "sheriff_candidates_finalized",
    "sheriff_pk_started",
    "exile_pk_started",
    "sheriff_vote_summary",
    "sheriff_badge_transferred",
    "sheriff_badge_destroyed",
    "sheriff_direction_chosen",
  ]);
  const project = (
    type: string,
    p: Record<string, unknown>,
    audience: readonly number[] | undefined,
    id: number,
  ): Record<string, unknown> | null => {
    if ((NOBLE_SECRET_BODY_EVENT_TYPES as readonly string[]).includes(type)) {
      if (
        ["noble_contract_closed", "secret_body_blocked"].includes(type) ||
        type.startsWith("noble_body_")
      )
        return null;
      if (["secret_body_revealed", "secret_body_reveal_speech"].includes(type))
        return structuredClone(p);
      return p.actorId === id && equal(audience, [id]) ? structuredClone(p) : null;
    }
    if (type === "demon_hunter_chosen")
      return id === demonId ? { policy: p.policy, day: p.day, targetId: p.targetId } : null;
    if (
      [
        "wolf_tactical_order",
        "wolf_discussion",
        "wolf_discussion_ended",
        "wolf_kill_vote_cast",
      ].includes(type)
    )
      return audience?.includes(id) ? structuredClone(p) : null;
    if (["seer_checked", "witch_potion_used", "witch_potion_skipped"].includes(type))
      return p.actorId === id ? structuredClone(p) : null;
    if (!publicTypes.has(type)) return null;
    if (type === "vote_summary") {
      const { tally: _tally, ...rest } = p;
      return structuredClone(rest);
    }
    return structuredClone(p);
  };
  const feedAt = new Map<number, Map<number, unknown>>();
  const openingAt = new Map<
    number,
    { day: number; phase: Phase; alive: number[]; state: RecordedNobleBodyState }
  >();
  const acceptEvent = (e: ReproductionRecord["events"][number]) => {
    const p = e.payload;
    if (e.type === "god_private_game_info") {
      check(
        !initialInfoSeen &&
          equal(p, {
            boardSize: 12,
            players: record.metadata.players.map((p, i) => ({
              id: p.id,
              seat: i + 1,
              name: p.name,
              role: p.role,
              camp: p.camp,
            })),
          }),
      );
      initialInfoSeen = true;
    }
    if (
      [
        "wolf_tactical_order",
        "wolf_discussion",
        "wolf_discussion_ended",
        "wolf_kill_vote_cast",
      ].includes(e.type)
    )
      check(
        equal(
          e.audience,
          [...alive].filter((id) => roster.get(id)!.camp === Camp.Wolf).sort((a, b) => a - b),
        ),
      );

    if (e.type === "phase_changed") {
      day = Number(p.day);
      phase = p.phase as Phase;
      if (phase === Phase.Voting) {
        exileExpected = null;
        votedOut = null;
        exileCandidates = null;
        exileRound = 1;
      }
    }
    election.accept(e, { day, phase, alive, idiot: -1, idiotRevealed: false });
    if (e.type === "witch_potion_used" || e.type === "witch_potion_skipped") {
      check(phase === Phase.Night && eventSeen.has(`knife/${day}`));
      mark(`potion/${day}`);
      const a = action(day, "witch", witchId);
      check(
        a?.name === "use_potion" &&
          equal(p, {
            actorId: witchId,
            targetId: a.args.target_id,
            potionType: a.args.potion_type,
          }),
      );
      check(
        e.type === (a.args.potion_type === "none" ? "witch_potion_skipped" : "witch_potion_used"),
      );
      if (a.args.potion_type !== "none") {
        check(alive.has(a.args.target_id));
        marks
          .get(a.args.target_id)!
          .push(a.args.potion_type === "heal" ? "HealMark" : "PoisonMark");
      }
    }
    if (e.type === "vote_summary") {
      check(phase === Phase.Voting && (p.round ?? 1) === exileRound);
      const stage = exileRound === 1 ? "voting" : "exile_pk_vote",
        eligible = [...alive].filter((id) => !exileCandidates?.includes(id)).sort((a, b) => a - b),
        tally: Record<string, number> = {},
        expectedVotes: unknown[] = [];
      check(
        equal(
          [...new Set(rows(day, stage).map((d) => d.actorId))].sort((a, b) => a - b),
          eligible,
        ),
      );
      for (const id of eligible) {
        const ds = rows(day, stage, id);
        let accepted: { target: number | null; abstain: boolean } | undefined;
        for (const d of ds) {
          if (d.outcome.kind !== "action" || d.outcome.action?.name !== "vote") continue;
          const a = d.outcome.action.args;
          if (typeof a.abstain !== "boolean") continue;
          if (a.abstain) {
            accepted = { target: null, abstain: true };
            break;
          }
          if (
            typeof a.target_id === "number" &&
            alive.has(a.target_id) &&
            (!exileCandidates || exileCandidates.includes(a.target_id))
          ) {
            accepted = { target: a.target_id, abstain: false };
            break;
          }
        }
        const vote = accepted ?? { target: null, abstain: true };
        expectedVotes.push({
          actorId: id,
          targetId: vote.target,
          abstain: vote.abstain,
          weight: vote.abstain ? 0 : votes.get(id)!.weight,
          ...(!accepted ? { fallback: true } : {}),
        });
        if (vote.target !== null)
          tally[vote.target] = (tally[vote.target] ?? 0) + votes.get(id)!.weight;
      }
      const entries = Object.entries(tally).sort(
          ([a, x], [b, y]) => y - x || Number(a) - Number(b),
        ),
        top = entries.length
          ? entries.filter(([, v]) => v === entries[0]![1]).map(([id]) => Number(id))
          : [];
      exileExpected = top.length === 1 ? top[0]! : null;
      check(equal(p.tally, tally) && p.target === exileExpected && equal(p.votes, expectedVotes));
      if (exileRound === 1 && top.length > 1) exileCandidates = top;
    }
    if (e.type === "exile_pk_started") {
      check(
        phase === Phase.Voting &&
          exileRound === 1 &&
          exileCandidates &&
          equal(p.candidates, exileCandidates),
      );
      exileRound = 2;
    }
    if ((NOBLE_SECRET_BODY_EVENT_TYPES as readonly string[]).includes(e.type)) {
      check(readNobleSecretBodyFact(e.type, p) && p.day === day);
      if (e.type === "noble_body_knife_committed") {
        mark(`knife/${day}`);
        check(phase === Phase.Night && p.actorId === nobleId);
        begin();
        const target = deriveKnife(nights.get(day)!);
        check(p.targetId === target);
        if (target !== null) marks.get(target)!.push("WolfKillMark");
      }
      if (e.type === "noble_body_native_damage_committed") {
        mark(`native/${day}`);
        check(phase === Phase.Night && p.actorId === bodyId && eventSeen.has(`knife/${day}`));
        const n = nights.get(day)!;
        check((!n.requiresBody || night().bodyChosen) && (!n.requiresNoble || night().nobleChosen));
        if (n.start.includes(witchId)) check(eventSeen.has(`potion/${day}`));
        if (n.start.includes(seerId)) {
          const a = action(day, "seer", seerId);
          check(a?.name === "check_identity" && n.start.includes(a.args.target_id));
        }
        prepare();
        for (const list of marks.values()) list.length = 0;
      }

      if (e.type === "noble_body_night_opened") {
        mark(`open/${day}`);
        begin();
        check(
          phase === Phase.Night &&
            p.actorId === nobleId &&
            equal(
              p.notifiedActorIds,
              [nobleId, bodyId].filter((id) => alive.has(id)),
            ),
        );
        for (const id of [nobleId, bodyId].filter((id) => alive.has(id)))
          check(seenNotice.has(`${day}/${id}`));
      }
      if (e.type === "noble_night_notified" || e.type === "secret_body_night_notified") {
        check(phase === Phase.Night);
        begin();
        const key = `${day}/${p.actorId}`;
        check(!seenNotice.has(key) && alive.has(Number(p.actorId)));
        seenNotice.add(key);
        if (e.type === "noble_night_notified") {
          check(p.actorId === nobleId);
          state.knowledge.noble = {
            wolfActionPolicy: state.noble.wolfActionPolicy,
            lastNotifiedNight: day,
            lastChoice: structuredClone(state.noble.lastChoice),
            contracts: structuredClone(state.noble.contracts),
          };
          check(equal(p, { policy, actorId: nobleId, day, ...state.knowledge.noble }));
          state.notices.push({
            kind: "night_noble",
            actorId: nobleId,
            day,
            known: structuredClone(state.knowledge.noble),
          });
        } else {
          check(p.actorId === bodyId);
          state.knowledge.body = {
            protectionRepeatPolicy: state.body.protectionRepeatPolicy,
            lastNotifiedNight: day,
            lastChoice: structuredClone(state.body.lastChoice),
            resource:
              state.body.body.kind === "intact"
                ? "intact"
                : state.body.body.kind === "exile_revealed"
                  ? "exile_revealed"
                  : "spent",
            publicRevealDay: state.body.body.kind === "exile_revealed" ? state.body.body.day : null,
          };
          check(equal(p, { policy, actorId: bodyId, day, ...state.knowledge.body }));
          state.notices.push({
            kind: "secret_body",
            actorId: bodyId,
            day,
            known: structuredClone(state.knowledge.body),
          });
        }
      }
      if (e.type === "secret_body_chosen" || e.type === "noble_servant_chosen") {
        check(phase === Phase.Night);
        begin();
        const body = e.type === "secret_body_chosen",
          id = body ? bodyId : nobleId,
          n = night(),
          a = action(day, body ? "secret_body" : "night_noble", id);
        check(
          p.actorId === id &&
            alive.has(id) &&
            a?.name === (body ? "protect_secret_body" : "choose_servant") &&
            equal(a.args, { target_id: p.targetId }) &&
            (p.targetId === null || alive.has(Number(p.targetId))),
        );
        if (body) {
          check(
            n.status === "open" &&
              nights.get(day)!.requiresBody &&
              !n.bodyChosen &&
              state.body.body.kind === "intact",
          );
          const old = state.body.lastChoice;
          check(
            state.body.protectionRepeatPolicy === "awa_repeat_v1" ||
              p.targetId === null ||
              old?.day !== day - 1 ||
              old.targetId !== p.targetId,
          );
          n.bodyChosen = true;
          state.body.lastChoice = { day, targetId: p.targetId as number | null };
          state.knowledge.body.lastChoice = structuredClone(state.body.lastChoice);
        } else {
          check(
            n.status === "open" &&
              nights.get(day)!.requiresNoble &&
              day >= 2 &&
              !n.nobleChosen &&
              !pending() &&
              p.targetId !== id,
          );
          n.nobleChosen = true;
          state.noble.lastChoice = { day, targetId: p.targetId as number | null };
          state.knowledge.noble.lastChoice = structuredClone(state.noble.lastChoice);
          if (p.targetId !== null) {
            const c = {
              id: `servant:night:${day}`,
              targetId: p.targetId as number,
              createdNight: day,
              expiresNight: day + 1,
              status: { kind: "pending" as const },
            };
            state.noble.contracts.push(c);
            state.knowledge.noble.contracts.push(structuredClone(c));
          }
        }
      }
      if (e.type === "noble_body_sources_committed") {
        mark(`sources/${day}`);
        const n = sourceCommits.has(day) ? nights.get(day)! : sources();
        check(
          equal(p, {
            policy,
            actorId: bodyId,
            day,
            blocked: n.blocked,
            deaths: Object.keys(n.final).map(Number),
            deathSources: n.final,
          }),
        );
      }
      if (e.type === "secret_body_blocked") {
        const n = sources();
        check(equal(p, { policy, actorId: bodyId, day, ...n.blocked }) && n.blocked !== null);
      }
      if (e.type === "noble_contract_closed") {
        mark(`closed/${p.contractId}`);
        if (!closures.has(String(p.contractId))) close(p);
        else {
          const c = state.noble.contracts.find((c) => c.id === p.contractId)!;
          check(c && c.status.kind !== "pending" && equal(p, makeClosed(c, c.status.kind)));
        }
      }
      if (e.type === "noble_body_death_committed") {
        mark(`death/${p.actorId}`);
        const id = Number(p.actorId);
        check(alive.has(id));
        if (phase === Phase.Night) check(equal(p.causes, nights.get(day)?.final[id]));
        else if (pendingBlast === id) {
          check(equal(p.causes, ["self_destruct"]));
          pendingBlast = null;
        } else
          check(
            phase === Phase.Voting &&
              votedOut === id &&
              exileExpected === id &&
              equal(p.causes, ["exile"]),
          );
        alive.delete(id);
        const c = pending();
        if (c?.targetId === id) c.status = { kind: "target_dead", day };
      }
      if (e.type === "secret_body_revealed") {
        check(
          phase === Phase.Voting &&
            exileExpected === bodyId &&
            p.actorId === bodyId &&
            alive.has(bodyId) &&
            state.body.body.kind === "intact",
        );
        state.body.body = { kind: "exile_revealed", day };
        state.knowledge.body.resource = "exile_revealed";
        state.knowledge.body.publicRevealDay = day;
      }
      if (e.type === "secret_body_reveal_speech") {
        check(
          phase === Phase.Voting &&
            exileExpected === bodyId &&
            p.actorId === bodyId &&
            state.body.body.kind === "exile_revealed",
        );
        const a = action(day, "awakened_idiot_reveal_speech", bodyId);
        check(a?.name === "speak" && p.text === sanitizeSpeechText(a.args.text));
        night().revealOpened = true;
        night().revealCompleted = true;
      }
    }
    if (e.type === "night_resolved") {
      check(
        phase === Phase.Night &&
          sourceCommits.has(day) &&
          equal(p.deaths, Object.keys(nights.get(day)!.final).map(Number)),
      );
      for (const id of p.deaths as number[]) {
        check(!alive.has(id));
        announcedDead.add(id);
      }
    }
    if (e.type === "voted_out") {
      check(phase === Phase.Voting && exileExpected === p.target && alive.has(Number(p.target)));
      votedOut = Number(p.target);
      announcedDead.add(Number(p.target));
    }
    if (e.type === "wolf_self_destruct") {
      check(
        ["on_pre_election", "on_pre_vote"].includes(String(p.window)) &&
          alive.has(Number(p.wolfId)) &&
          roster.get(Number(p.wolfId))?.camp === Camp.Wolf &&
          !(p.wolfId === nobleId && board.nightNoble!.wolfActionPolicy !== "standard"),
      );
      const confirmed = rows(day, String(p.window))
        .filter(
          (d) =>
            d.outcome.kind === "action" &&
            d.outcome.action?.name === "self_destruct" &&
            d.outcome.action.args.confirm === true,
        )
        .map((d) => d.actorId)
        .sort((a, b) => a - b);
      check(confirmed[0] === p.wolfId);
      pendingBlast = Number(p.wolfId);
      announcedDead.add(Number(p.wolfId));
    }
    if (e.type === "sheriff_elected") {
      check(sheriff === null && p.winnerId === election.winner && alive.has(Number(p.winnerId)));
      sheriff = Number(p.winnerId);
      for (const id of alive) {
        votes.set(id, { weight: id === sheriff ? 1.5 : 1, canVote: true });
        badges.set(id, {
          isSheriff: id === sheriff,
          destroyed: false,
          voteWeight: 1.5,
          handoffPolicy: "awa_holder_choice_v1",
        } as any);
      }
    }
    if (e.type === "sheriff_badge_transferred" || e.type === "sheriff_badge_destroyed") {
      const from = e.type === "sheriff_badge_transferred" ? Number(p.fromId) : Number(p.targetId),
        to = e.type === "sheriff_badge_transferred" ? Number(p.toId) : null;
      check(sheriff === from && !alive.has(from) && (to === null || alive.has(to)));
      const choices = rows(day, "sheriff_badge_choice", from);
      check(choices.length === 1 && choices[0]!.outcome.kind === "action");
      const a = choices[0]!.outcome.action,
        target = a?.name === "choose_badge_successor" ? a.args.target_id : null,
        valid =
          typeof target === "number" &&
          Number.isSafeInteger(target) &&
          alive.has(target) &&
          badges.get(target)?.destroyed === false;
      check(to === (valid ? target : null));
      badges.set(from, { ...badges.get(from)!, isSheriff: false, destroyed: true } as any);
      votes.set(from, { weight: 1, canVote: true });
      sheriff = to;
      if (to !== null) {
        badges.set(to, {
          isSheriff: true,
          destroyed: false,
          voteWeight: 1.5,
          handoffPolicy: "awa_holder_choice_v1",
        } as any);
        votes.set(to, { weight: 1.5, canVote: true });
      }
    }
    if (e.type === "game_over") {
      const wolves = [...alive].filter((id) => roster.get(id)!.camp === Camp.Wolf),
        gods = [...alive].filter(
          (id) => roster.get(id)!.camp === Camp.Good && roster.get(id)!.role !== Role.Villager,
        ),
        villagers = [...alive].filter((id) => roster.get(id)!.role === Role.Villager),
        winner =
          wolves.length === 0
            ? Camp.Good
            : gods.length === 0 || villagers.length === 0
              ? Camp.Wolf
              : null;
      check(winner !== null && p.winner === winner);
    }
    for (const id of roster.keys()) {
      const p = project(e.type, e.payload, e.audience, id);
      if (p) {
        const list = observed.get(id)!;
        list.push({ seq: list.length + 1, type: e.type, payload: p });
      }
    }
  };
  const acceptOp = (op: ReproductionRecord["operations"][number]) => {
    const p = op.output;
    if (op.op === "noble_contract_closed") {
      check(p && p.day === day && op.phase === phase && op.status === "ok");
      close(p);
    }
    if (op.op === "noble_body_night_opened") {
      begin();
      check(
        p &&
          p.day === day &&
          equal(
            p.notifiedActorIds,
            [nobleId, bodyId].filter((id) => alive.has(id)),
          ),
      );
    }
  };
  const cpAt = new Map<string, RecordedCheckpoint[]>();
  for (const cp of record.checkpoints) {
    check(
      cp.nobleBody &&
        cp.operationCount !== undefined &&
        cp.settlementCount !== undefined &&
        cp.decisionCount !== undefined,
    );
    const key = `${cp.eventCount}/${record.finalized ? cp.operationCount : 0}`,
      list = cpAt.get(key) ?? [];
    list.push(cp);
    cpAt.set(key, list);
  }
  const checkpoint = (cp: RecordedCheckpoint) => {
    check(cp.decisionCount! <= record.decisions.length && cp.settlementCount! <= cp.decisionCount!);
    check(
      cp.decisionCount ===
        record.decisions.filter(
          (d) =>
            d.openedAtEventCount !== undefined &&
            d.openedAtEventCount <= cp.eventCount &&
            d.day <= cp.cycle,
        ).length,
    );
    check(
      cp.cycle === 0
        ? cp.settlementCount === 0 && cp.snapshot.day === 1
        : cp.complete
          ? cp.settlementCount === cp.decisionCount
          : cp.settlementCount! >=
            Math.max(
              0,
              ...record.decisions
                .slice(0, cp.decisionCount)
                .filter((d) => d.settleOrder !== undefined)
                .map((d) => d.settleOrder ?? 0),
            ),
    );
    const advanced = cp.complete && !cp.snapshot.gameOver && cp.cycle > 0,
      completedNight = state.nights.at(-1);
    check(!advanced || (completedNight && completedNight.day === cp.cycle));
    check(
      cp.snapshot.phase === phase && cp.snapshot.day === (advanced ? completedNight!.day + 1 : day),
    );
    const expected = structuredClone(state),
      n = expected.nights.at(-1);
    if (!cp.complete && n) {
      if (!n.bodyResolved) n.status = "aborted";
      const reveal = rows(cp.cycle, "awakened_idiot_reveal_speech", bodyId);
      if (reveal.length) n.revealOpened = true;
    }
    check(equal(cp.nobleBody, expected));
    snapshots.set(cp, expected);
    for (const p of cp.players) {
      const original = roster.get(p.id);
      check(
        original &&
          p.role === original.role &&
          p.camp === original.camp &&
          p.name === original.name &&
          p.seat === p.id &&
          p.alive === alive.has(p.id) &&
          equal(p.vote, votes.get(p.id)) &&
          equal(p.badge, badges.get(p.id)) &&
          equal(p.marks, marks.get(p.id)) &&
          equal(p.victory, { affiliations: [{ kind: "faction", faction: original.camp }] }),
      );
    }
  };
  let oi = 0;
  const ops = record.finalized ? record.operations : [];
  for (let ei = 0; ei <= record.events.length; ei++) {
    const verify = () => {
      for (const cp of cpAt.get(`${ei}/${oi}`) ?? []) checkpoint(cp);
    };
    verify();
    while (oi < ops.length && ops[oi]!.event_count === ei) {
      acceptOp(ops[oi]!);
      oi++;
      verify();
    }
    if (oi < ops.length)
      check(
        ops[oi]!.event_count !== undefined &&
          ops[oi]!.event_count! > ei &&
          ops[oi]!.event_count! <= record.events.length,
      );
    openingAt.set(ei, { day, phase, alive: [...alive], state: structuredClone(state) });
    feedAt.set(ei, new Map([...observed].map(([id, feed]) => [id, structuredClone(feed)])));
    if (ei < record.events.length) acceptEvent(record.events[ei]!);
  }
  check(oi === ops.length && snapshots.size === record.checkpoints.length);
  if (record.finalized) {
    const last = record.checkpoints.at(-1)!;
    check(
      last.eventCount === record.events.length &&
        last.operationCount === record.operations.length &&
        last.decisionCount === record.decisions.length &&
        last.settlementCount === record.decisions.filter((d) => d.settleOrder !== undefined).length,
    );
  }

  check(initialInfoSeen);
  const settled = record.decisions
    .filter((d) => d.settleOrder !== undefined)
    .map((d) => d.settleOrder!)
    .sort((a, b) => a - b);
  check(
    equal(
      settled,
      Array.from({ length: settled.length }, (_, i) => i + 1),
    ),
  );
  for (const d of record.decisions)
    check(
      d.settleOrder === undefined
        ? d.outcome.kind === "pending"
        : d.openedAfterSettlement < d.settleOrder,
    );
  for (const d of record.decisions) {
    check(
      d.request.actorId === d.actorId &&
        d.request.context.day === d.day &&
        d.request.context.stage === d.stage &&
        roster.has(d.actorId),
    );

    const o = d.openedAtEventCount === undefined ? undefined : openingAt.get(d.openedAtEventCount);
    check(o && o.phase !== Phase.GameOver && o.day === d.day && d.request.phase === o.phase);
    if (["secret_body", "night_noble"].includes(d.stage)) {
      const body = d.stage === "secret_body",
        actor = body ? bodyId : nobleId,
        tool = body ? "protect_secret_body" : "choose_servant",
        n = nights.get(d.day);
      check(
        o.phase === Phase.Night &&
          o.alive.includes(actor) &&
          d.actorId === actor &&
          d.turn === 1 &&
          n &&
          (body ? n.requiresBody : n.requiresNoble) &&
          equal(d.request.allowedTools, [tool]) &&
          d.request.context.allow_fallback === false &&
          d.request.context.action_failure_policy === "error" &&
          d.request.context.turn_constraints.min_valid_actions === 1 &&
          d.request.context.turn_constraints.max_valid_actions === 1 &&
          equal(d.request.context.turn_constraints.required_any_tools, [tool]),
      );
      const eventIndex = record.events.findIndex(
        (e) =>
          e.type === (body ? "secret_body_chosen" : "noble_servant_chosen") &&
          e.payload.day === d.day,
      );
      if (eventIndex >= 0) check(d.openedAtEventCount! <= eventIndex);
      const last = o.state.body.lastChoice,
        targets = o.alive
          .filter((id) =>
            body
              ? !(
                  board.awakenedIdiot!.protectionRepeatPolicy === "awa_nonconsecutive_nights_v1" &&
                  last?.day === d.day - 1 &&
                  last.targetId === id
                )
              : id !== nobleId,
          )
          .sort((a, b) => a - b);
      check(
        equal(
          body ? d.request.context.secret_body_candidates : d.request.context.servant_candidates,
          targets,
        ),
      );
    }
    const f = d.request.context.visible_events,
      expected =
        d.openedAtEventCount === undefined
          ? undefined
          : feedAt.get(d.openedAtEventCount)?.get(d.actorId);
    check(d.openedAtEventCount !== undefined && equal(expected, f));
  }

  if (record.finalized) {
    for (const type of [
      "noble_body_night_opened",
      "noble_body_knife_committed",
      "noble_body_native_damage_committed",
      "noble_body_sources_committed",
      "noble_body_death_committed",
    ]) {
      const es = record.events.map((e, index) => ({ e, index })).filter((x) => x.e.type === type),
        os = record.operations.filter((o) => o.op === type);
      check(es.length === os.length);
      for (let i = 0; i < es.length; i++) {
        const { e, index } = es[i]!,
          op = os[i]!,
          p = e.payload;
        const output =
          type === "noble_body_death_committed"
            ? { policy, playerId: p.actorId, day: p.day, causes: p.causes }
            : p;
        const eventPhase = openingAt.get(index + 1)!.phase;
        check(
          op.scope ===
            (["noble_body_night_opened", "noble_body_knife_committed"].includes(type)
              ? "phase_pipeline"
              : "resolution") &&
            op.status === "ok" &&
            op.phase === eventPhase &&
            op.actor_id === undefined &&
            op.input === undefined &&
            op.reason === undefined &&
            op.event_count === index + 1 &&
            equal(op.output, output),
        );
      }
    }
  }
  return {
    at: (cp) => {
      const found = snapshots.get(cp);
      check(found);
      return structuredClone(found);
    },
    nights,
  };
}

/**
 * 负责独立验证动物梦境的行动、票型、死亡与玩家知情前缀。
 * 输入为规范板子、已记录决定／事件与 checkpoint；输出为原一致性结果或明确拒绝。
 * 原动物状态、死亡准备 和投票账本在本地重建，不调用 live World／效果／投票／死亡结算。
 * 归档事实不授予真实资源或公开许可，完整事件次序、未完成前缀和首失败政策保持。
 */
import { animalFeedAt } from "./feed-evidence";
import { isDeepStrictEqual as equal } from "node:util";
import { ANIMAL_DREAM_EVENT_TYPES } from "@ai-werewolf-arena/game-contract/facts/animal-dream";
import { isAnimalDreamPreset } from "../../board-support";
import { ANIMAL_DREAM_POLICY as policy } from "@ai-werewolf-arena/game-contract";
import type { ReproductionRecord } from "../../../recording/reproduction";
function check(value: unknown): asserts value {
  if (!value) throw Error("reproduction_animal_dream_invalid");
}
/** 独立核算已记录行动、原座位与实际发表前缀。
 * 不使用 World、runtime owner、伤害结算、票型选择或可见性投影。 */
export function validateAnimalDreamRecord(r: ReproductionRecord): void {
  const board = r.metadata.normalizedBoard;
  const animal = (type: string) => (ANIMAL_DREAM_EVENT_TYPES as readonly string[]).includes(type);
  if (!board.animalDream) {
    check(
      !board.whiteCat &&
        !board.pufferfish &&
        board.bear?.signalPolicy !== "netease_dawn_live_v1" &&
        !board.roleSetups.some((row) =>
          ["white_cat", "fox_cub", "pufferfish"].includes(row.role),
        ) &&
        !r.checkpoints.some((cp) =>
          cp.players.some((p) =>
            ["whiteCat", "foxCub", "pufferfish"].some((key) => Object.hasOwn(p.privateState, key)),
          ),
        ) &&
        !r.events.some((e) => animal(e.type)) &&
        !r.checkpoints.some((c) => c.animalDream) &&
        !r.decisions.some(
          (d) =>
            d.stage === "fox_distract" ||
            d.stage === "puffer_reaction" ||
            d.request.context.fox_candidates !== undefined,
        ),
    );
    return;
  }
  check(isAnimalDreamPreset(board));
  const roster = new Map(r.metadata.players.map((p) => [p.id, p]));
  check(
    roster.size === 12 &&
      [...roster.keys()].sort((a, b) => a - b).every((id, i) => id === i + 1) &&
      [...roster.values()].every(
        (p) => p.camp === (["wolf", "wolf_beauty"].includes(p.role) ? "wolf" : "good"),
      ),
  );
  const roleId = (role: string) => {
    const rows = [...roster.values()].filter((p) => p.role === role);
    check(rows.length === 1);
    return rows[0]!.id;
  };
  const catId = roleId("white_cat"),
    foxId = roleId("fox_cub"),
    pufferId = roleId("pufferfish"),
    beautyId = roleId("wolf_beauty");
  const wolfIds = [...roster.values()].filter((p) => p.camp === "wolf").map((p) => p.id);
  let day = 1,
    phase = "night",
    completed = 0,
    currentUnit: number | null = null,
    unitKind: "exile" | "skipped_day" = "exile";
  let fox: any = { policy, usedNight: null, history: [] },
    puffer: any = { policy, usedDay: null, knifeDeathDay: null, history: [] },
    cat: any = { policy, form: { kind: "veiled" } };
  let effect: any = null,
    charm: number | null = null,
    charmDay: number | null = null,
    knife: number | null = null,
    exile: number | null = null,
    blast: number | null = null;
  let latestNight: any = null,
    latestUnit: any = null,
    blockedDay: number | null = null;
  const bearHistory: Array<{ day: number; roared: boolean }> = [];
  let charmHistory: Array<{ day: number; targetId: number | null }> = [],
    beautyExiled = false;
  let pkCandidates: number[] = [];
  let knifeVotes: any[] = [],
    ballots = new Map<number, any[]>(),
    retaliation: number[] = [],
    prepared: number[] | null = null,
    expiry: number | null = null;
  let result: any = null;
  const badges = new Map(
    [...roster.keys()].map((id) => [
      id,
      { isSheriff: false, destroyed: false, voteWeight: 1.5 } as {
        isSheriff: boolean;
        destroyed: boolean;
        voteWeight: number;
        handoffPolicy?: string;
      },
    ]),
  );
  const publicDead = new Set<number>();
  const alive = new Set(roster.keys()),
    snapshots = new Map<
      number,
      {
        alive: number[];
        publicDead: number[];
        fox: any;
        puffer: any;
        cat: any;
        completed: number;
        night: any;
        unit: any;
        effect: any;
        blockedDay: number | null;
        beauty: any;
        bear: any;
        day: number;
        phase: string;
        result: any;
        badges: Map<number, any>;
      }
    >();
  const acceptedSources = new Set<number>();
  const paidChoices = new Set<number>(),
    opened = new Set<number>();
  const save = (cursor: number) =>
    snapshots.set(cursor, {
      alive: [...alive],
      publicDead: [...publicDead],
      day,
      phase,
      result: structuredClone(result),
      badges: structuredClone(badges),
      fox: structuredClone(fox),
      puffer: structuredClone(puffer),
      cat: structuredClone(cat),
      completed,
      night: structuredClone(latestNight),
      unit: structuredClone(latestUnit),
      effect: structuredClone(effect),
      blockedDay,
      beauty: { targetId: charm, lastActedDay: charmDay, history: structuredClone(charmHistory) },
      bear: { history: structuredClone(bearHistory) },
    });
  const tool = (d: ReproductionRecord["decisions"][number]) =>
    d.outcome.kind === "action" ? d.outcome.action : null;
  const matchDecision = (type: string, actor: number, di: number, cursor: number) => {
    const name = type === "animal_fox_chosen" ? "fox_distract" : "puffer_retaliate";
    const ds = r.decisions.filter(
      (d) =>
        d.actorId === actor &&
        d.day === di &&
        tool(d)?.name === name &&
        d.openedAtEventCount! <= cursor &&
        d.settleOrder !== undefined,
    );
    check(ds.length === 1 && !paidChoices.has(r.decisions.indexOf(ds[0]!)));
    check(
      r.decisions
        .filter((d) => d.openedAtEventCount! > cursor)
        .every((d) => d.openedAfterSettlement >= ds[0]!.settleOrder!),
    );
    paidChoices.add(r.decisions.indexOf(ds[0]!));
    return tool(ds[0]!)!;
  };
  const matchSource = (name: string, actorId: number, payload: any, cursor: number) => {
    const candidates = r.decisions.filter(
      (d, index) =>
        !acceptedSources.has(index) &&
        d.actorId === actorId &&
        d.day === day &&
        d.openedAtEventCount! <= cursor &&
        tool(d)?.name === name,
    );
    const found = candidates.find((d) => {
      const args: any = tool(d)!.args;
      return name === "charm"
        ? args.target_id === payload.targetId
        : args.abstain === true || args.target_id === null
          ? payload.abstain === true && payload.targetId === null
          : payload.abstain === false && args.target_id === payload.targetId;
    });
    if (!found) {
      check(payload.fallback === true && payload.abstain === true && payload.targetId === null);
      return;
    }
    acceptedSources.add(r.decisions.indexOf(found));
  };
  const tallyTarget = (votes: any[], min = false) => {
    const tally = new Map<number, number>();
    for (const v of votes)
      if (!v.abstain && v.targetId !== null)
        tally.set(v.targetId, (tally.get(v.targetId) ?? 0) + (v.weight ?? 1));
    const maximum = Math.max(0, ...tally.values()),
      ids = [...tally]
        .filter(([, n]) => n === maximum)
        .map(([id]) => id)
        .sort((a, b) => a - b);
    return ids.length === 1 || min ? (ids[0] ?? null) : null;
  };
  const sourceFor = (id: number, sourcePhase: string): string[] => {
    const sources: string[] = [];
    if (knife === id && sourcePhase !== "voting") sources.push("wolf_kill");
    if (blast === id) sources.push("self_destruct");
    if (exile === id && sourcePhase === "voting") sources.push("exile");
    if (retaliation.includes(id) && sourcePhase === "voting") sources.push("puffer_retaliation");
    if (
      !sources.length &&
      charm === id &&
      beautyExiled &&
      !alive.has(beautyId) &&
      puffer.knifeDeathDay !== day &&
      !effect?.beautyBlocked
    )
      sources.push("charm");
    return sources;
  };
  save(0);
  for (let i = 0; i < r.events.length; i++) {
    for (const d of r.decisions.filter(
      (d) => d.openedAtEventCount === i && ["voting", "exile_pk_vote"].includes(d.stage),
    )) {
      if (currentUnit === null) {
        currentUnit = completed + 1;
        unitKind = "exile";
        latestUnit = {
          number: currentUnit,
          day,
          kind: unitKind,
          status: "open",
          expiryPrepared: false,
          expiryCatId: null,
          finalRound: null,
          ballots: [],
          puffer: null,
        };
      }
    }
    const e = r.events[i]!,
      p: any = e.payload;
    if (
      [
        "wolf_tactical_order",
        "wolf_discussion",
        "wolf_discussion_ended",
        "wolf_kill_vote_cast",
      ].includes(e.type)
    )
      check(
        equal(
          e.audience,
          wolfIds.filter((id) => alive.has(id)).sort((a, b) => a - b),
        ),
      );
    if (e.type === "sheriff_elected") {
      check(alive.has(p.winnerId));
      for (const id of alive)
        badges.set(id, {
          isSheriff: id === p.winnerId,
          destroyed: false,
          voteWeight: 1.5,
          handoffPolicy: "awa_holder_choice_v1",
        });
    }
    if (e.type === "sheriff_badge_transferred" || e.type === "sheriff_badge_destroyed") {
      const from = e.type === "sheriff_badge_transferred" ? p.fromId : p.targetId,
        prior = badges.get(from)!;
      check(prior?.isSheriff && !prior.destroyed && !alive.has(from));
      badges.set(from, { ...prior, isSheriff: false, destroyed: true });
      if (e.type === "sheriff_badge_transferred") {
        check(alive.has(p.toId) && p.toId !== from);
        badges.set(p.toId, {
          ...badges.get(p.toId)!,
          isSheriff: true,
          destroyed: false,
          voteWeight: 1.5,
          handoffPolicy: "awa_holder_choice_v1",
        });
      }
    }

    if (e.type === "phase_changed") {
      day = p.day;
      phase = p.phase;
      if (phase === "night") {
        beautyExiled = false;
        pkCandidates = [];
        knifeVotes = [];
        ballots = new Map();
        retaliation = [];
        exile = null;
        blast = null;
        currentUnit = null;
        knife = null;
      }
    }
    if (e.type === "animal_night_opened") {
      check(p.day === day && !opened.has(day));
      opened.add(day);
      latestNight = {
        day,
        status: "open",
        requiresFox: day >= 2 && alive.has(foxId) && fox.usedNight === null,
        foxPaid: false,
      };
      blockedDay = null;
      effect = null;
    }
    if (e.type === "animal_fox_chosen") {
      check(
        opened.has(day) &&
          day >= 2 &&
          p.day === day &&
          p.actorId === foxId &&
          alive.has(foxId) &&
          fox.usedNight === null,
      );
      const c = matchDecision(e.type, foxId, day, i);
      check(
        equal(c.args, { target_id: p.targetId }) && (p.targetId === null || alive.has(p.targetId)),
      );
      fox.history.push({ day, targetId: p.targetId });
      latestNight.foxPaid = true;
      if (p.targetId !== null) fox.usedNight = day;
    }
    if (e.type === "animal_fox_effect") {
      const last = fox.history.at(-1);
      check(
        last?.day === day &&
          last.targetId === p.targetId &&
          p.targetId !== null &&
          p.actorId === foxId &&
          p.day === day,
      );
      effect = {
        day,
        targetId: p.targetId,
        knifeBlocked: wolfIds.includes(p.targetId),
        beautyBlocked: p.targetId === beautyId,
      };
      check(equal(p, { policy, actorId: foxId, ...effect }));
      if (effect.beautyBlocked) charm = null;
    }
    if (e.type === "animal_knife_notified") {
      check(
        day === 1 || !alive.has(foxId) || fox.usedNight !== null || fox.history.at(-1)?.day === day,
      );
      check(
        p.day === day &&
          wolfIds.includes(p.actorId) &&
          alive.has(p.actorId) &&
          p.eligible === !effect?.knifeBlocked,
      );
    }
    if (e.type === "wolf_kill_vote_cast") {
      matchSource("kill_vote", p.actorId, p, i);
      check(
        opened.has(day) &&
          !effect?.knifeBlocked &&
          wolfIds.includes(p.actorId) &&
          alive.has(p.actorId),
      );
      knifeVotes.push(p);
      knife = tallyTarget(knifeVotes, true);
    }
    if (e.type === "charm_applied") {
      matchSource("charm", p.actorId, p, i);
      check(!effect?.beautyBlocked && p.actorId === beautyId && alive.has(beautyId));
      charm = p.targetId;
      charmDay = day;
      charmHistory.push({ day, targetId: charm });
    }
    if (e.type === "animal_beauty_notified")
      check(
        equal(p, {
          policy,
          day,
          actorId: beautyId,
          charmAllowed: phase === "night" && !effect?.beautyBlocked,
          linkAllowed: puffer.knifeDeathDay !== day,
          targetId: charm,
          lastActedDay: charmDay,
          history: charmHistory,
        }),
      );
    if (e.type === "exile_pk_started") {
      const votes = ballots.get(1)!;
      check(votes);
      const tally = new Map<number, number>();
      for (const v of votes)
        if (!v.abstain) tally.set(v.targetId, (tally.get(v.targetId) ?? 0) + v.weight);
      const maximum = Math.max(0, ...tally.values());
      pkCandidates = [...tally]
        .filter(([, n]) => n === maximum)
        .map(([id]) => id)
        .sort((a, b) => a - b);
      check(pkCandidates.length > 1 && equal(p.candidates, pkCandidates));
    }
    if (e.type === "vote_cast") {
      check(!pkCandidates.includes(p.actorId));
      matchSource("vote", p.actorId, p, i);
    }

    if (e.type === "vote_summary") {
      check(Array.isArray(p.votes));
      const round = p.round ?? 1;
      check(!ballots.has(round));
      const raw = r.events
        .slice(0, i)
        .filter((x) => x.type === "vote_cast")
        .slice(-p.votes.length)
        .map((x) => {
          const { fallback: _fallback, ...v } = x.payload;
          return v;
        });
      check(
        equal(raw, p.votes) && new Set(p.votes.map((v: any) => v.actorId)).size === p.votes.length,
      );
      check(
        p.votes.every(
          (v: any) =>
            alive.has(v.actorId) &&
            (v.abstain ? v.weight === 0 : alive.has(v.targetId) && [1, 1.5].includes(v.weight)),
        ),
      );
      const eligible = [...alive].filter((id) => round === 1 || !pkCandidates.includes(id));
      check(
        equal(
          p.votes.map((v: any) => v.actorId).sort((a: number, b: number) => a - b),
          eligible.sort((a, b) => a - b),
        ),
      );
      if (round === 2)
        check(
          pkCandidates.length > 1 &&
            p.votes.every((v: any) => v.abstain || pkCandidates.includes(v.targetId)),
        );
      check(p.target === tallyTarget(p.votes));
      ballots.set(round, p.votes);
      check(latestUnit !== null);
      latestUnit.ballots.push({ round, votes: structuredClone(p.votes) });
      const scores = new Map<number, number>();
      for (const v of p.votes)
        if (!v.abstain) scores.set(v.targetId, (scores.get(v.targetId) ?? 0) + v.weight);
      const maximum = Math.max(0, ...scores.values()),
        tied = maximum > 0 ? [...scores].filter(([, n]) => n === maximum) : [];
      if (round === 2 || tied.length <= 1) {
        latestUnit.finalRound = round;
        const selected = board.pufferfish!.ballotPolicy === "awa_first_ballot_v1" ? 1 : round;
        const targets = ballots
          .get(selected)!
          .filter((v) => !v.abstain && v.targetId === pufferId)
          .map((v) => v.actorId)
          .sort((a, b) => a - b);
        latestUnit.puffer =
          alive.has(pufferId) && puffer.usedDay === null && targets.length
            ? { targetIds: targets, paid: false, activated: false, closed: false }
            : null;
      }
      exile = p.target;
    }
    if (e.type === "animal_puffer_decided") {
      check(
        p.actorId === pufferId &&
          p.day === day &&
          alive.has(pufferId) &&
          puffer.usedDay === null &&
          currentUnit !== null,
      );
      const c = matchDecision(e.type, pufferId, day, i);
      check(equal(c.args, { activate: p.activate }));
      const round =
        board.pufferfish!.ballotPolicy === "awa_first_ballot_v1" ? 1 : Math.max(...ballots.keys());
      const targets = (ballots.get(round) ?? [])
        .filter((v) => !v.abstain && v.targetId === pufferId)
        .map((v) => v.actorId)
        .sort((a, b) => a - b);
      check(targets.length > 0);
      puffer.history.push({ day, activate: p.activate, targetIds: targets });
      latestUnit.puffer = { targetIds: targets, paid: true, activated: p.activate, closed: true };
      if (p.activate) {
        puffer.usedDay = day;
        retaliation = targets;
      }
    }
    if (e.type === "animal_puffer_targets")
      check(
        p.day === day &&
          p.actorId === pufferId &&
          puffer.usedDay === day &&
          equal(p.targetIds, retaliation) &&
          p.round ===
            (board.pufferfish!.ballotPolicy === "awa_first_ballot_v1"
              ? 1
              : Math.max(...ballots.keys())),
      );
    if (e.type === "wolf_self_destruct") {
      check(wolfIds.includes(p.wolfId) && p.wolfId !== beautyId);
      blast = p.wolfId;
      currentUnit = completed + 1;
      unitKind = "skipped_day";
      latestUnit = {
        number: currentUnit,
        day,
        kind: unitKind,
        status: "open",
        expiryPrepared: false,
        expiryCatId: null,
        finalRound: null,
        ballots: [],
        puffer: null,
      };
    }
    if (e.type === "animal_wave_prepared") {
      check(p.day === day && prepared === null);
      const candidates: number[] = p.proposedIds;
      check(candidates.every((id) => alive.has(id) && sourceFor(id, p.phase).length > 0));
      const blocked = candidates.includes(catId) && cat.form.kind !== "expired" ? catId : null;
      check(p.blockedCatId === blocked);
      if (blocked !== null && cat.form.kind === "veiled") {
        const clockUnit =
          unitKind === "exile"
            ? currentUnit
            : board.whiteCat!.skippedVotePolicy === "awa_expire_on_skipped_day_v1"
              ? currentUnit
              : null;
        cat.form = {
          kind: "deferred",
          deferred: {
            day,
            phase: p.phase,
            firstSources: sourceFor(catId, p.phase),
            firstUnit: clockUnit,
            expiresAfterUnit: clockUnit === null ? completed + 1 : clockUnit + 1,
          },
        };
      }
      prepared = candidates.filter((id) => id !== blocked);
      if (currentUnit !== null && latestUnit?.day === day) latestUnit.expiryPrepared = true;
    }
    if (e.type === "animal_cat_revealed")
      check(
        p.actorId === catId &&
          p.day === day &&
          cat.form.kind === "deferred" &&
          cat.form.deferred.day === day &&
          alive.has(catId),
      );
    if (e.type === "animal_cat_expiry_prepared") {
      check(
        p.actorId === catId &&
          p.day === day &&
          p.unit === currentUnit &&
          p.unitKind === unitKind &&
          cat.form.kind === "deferred",
      );
      const d = cat.form.deferred;
      check(
        unitKind === "exile"
          ? currentUnit! >= d.expiresAfterUnit
          : board.whiteCat!.skippedVotePolicy === "awa_expire_on_skipped_day_v1" &&
              (currentUnit! >= d.expiresAfterUnit ||
                (d.day === day && d.firstUnit === currentUnit)),
      );
      cat.form = { kind: "expired", deferred: d, day, unit: currentUnit, unitKind };
      expiry = catId;
      latestUnit.expiryPrepared = true;
      latestUnit.expiryCatId = catId;
    }
    if (e.type === "animal_wave_committed") {
      check(p.day === day && prepared !== null);
      const expected = [...prepared!];
      if (expiry !== null && !expected.includes(expiry)) expected.push(expiry);
      check(
        equal(
          [...p.deaths].sort((a, b) => a - b),
          expected.sort((a, b) => a - b),
        ),
      );
      for (const id of p.deaths) {
        check(alive.has(id));
        const sources =
          id === expiry
            ? sourceFor(id, p.phase).filter((s) => s === "exile" || s === "puffer_retaliation")
            : sourceFor(id, p.phase);
        if (id === expiry) sources.push("white_cat_expiry");
        check(equal([...p.deathSources[String(id)]].sort(), sources.sort()));
        alive.delete(id);
        if (id === beautyId) beautyExiled = sources.includes("exile");
        if (id === pufferId && sources.includes("wolf_kill")) {
          puffer.knifeDeathDay = day;
          blockedDay = day;
        }
      }
      prepared = null;
      expiry = null;
    }
    // 空波／仅延后死亡的波不发表实际 batch，但仍消耗一次 preparation。
    if (
      prepared?.length === 0 &&
      expiry === null &&
      !["animal_wave_prepared", "animal_cat_revealed", "animal_cat_expiry_prepared"].includes(
        e.type,
      )
    )
      prepared = null;
    if (e.type === "animal_unit_completed") {
      check(p.day === day && p.unit === currentUnit && p.kind === unitKind);
      if (
        unitKind === "exile" ||
        board.whiteCat!.skippedVotePolicy === "awa_expire_on_skipped_day_v1"
      )
        completed++;
      latestUnit.status = "closed";
      latestUnit.expiryPrepared = true;
      if (latestUnit.puffer) latestUnit.puffer.closed = true;
      currentUnit = null;
      retaliation = [];
      exile = null;
      blast = null;
    }
    if (e.type === "game_over") result = structuredClone(p);
    if (e.type === "game_over" && p.outcome?.kind === "victory") {
      check(latestUnit === null || latestUnit.status === "closed");
      check(
        !(
          beautyExiled &&
          charm !== null &&
          alive.has(charm) &&
          puffer.knifeDeathDay !== day &&
          !effect?.beautyBlocked &&
          !(charm === catId && cat.form.kind === "deferred")
        ),
      );
      const wolves = wolfIds.filter((id) => alive.has(id)),
        gods = [catId, foxId, pufferId, roleId("bear")].filter((id) => alive.has(id)),
        villagers = [...roster.values()].filter((x) => x.role === "villager" && alive.has(x.id));
      const winner =
        gods.length === 0 || villagers.length === 0 ? "wolf" : wolves.length === 0 ? "good" : null;
      check(winner !== null && p.winner === winner);
      check(
        equal(
          p.outcome.winningPlayerIds,
          [...roster.values()]
            .filter((x) => x.camp === winner)
            .map((x) => x.id)
            .sort((a, b) => a - b),
        ),
      );
    }
    if (["night_resolved", "additional_deaths", "voted_out"].includes(e.type)) {
      const deaths = e.type === "voted_out" ? [p.target] : p.deaths;
      check(
        Array.isArray(deaths) &&
          deaths.every(
            (id: number) =>
              roster.has(id) && (!alive.has(id) || (prepared ?? []).includes(id) || id === expiry),
          ),
      );
      deaths.forEach((id: number) => publicDead.add(id));
    }
    if (e.type === "bear_roared") {
      const bear = roleId("bear"),
        seats = r.checkpoints[0]!.players.slice()
          .sort((a, b) => a.seat - b.seat)
          .map((p) => p.id),
        position = seats.indexOf(bear);
      const neighbor = (step: number) => {
        for (let n = 1; n < seats.length; n++) {
          const id = seats[(position + step * n + seats.length * 2) % seats.length]!;
          if (alive.has(id)) return id;
        }
        return null;
      };
      const expected =
        alive.has(bear) &&
        [neighbor(-1), neighbor(1)].some((id) => id !== null && wolfIds.includes(id));
      check(p.roared === expected);
      check(p.day === day && !bearHistory.some((row) => row.day === day));
      bearHistory.push({ day, roared: p.roared });
    }
    if (latestNight && phase !== "night") latestNight.status = "normal";
    save(i + 1);
  }
  if (r.finalized)
    for (const [type, op] of [
      ["wolf_kill_vote_cast", "wolf_kill_vote_cast"],
      ["vote_cast", "vote_cast"],
    ]) {
      for (const [i, e] of r.events.entries())
        if (e.type === type)
          check(
            r.operations.some(
              (o) =>
                o.op === op &&
                o.actor_id === e.payload.actorId &&
                o.event_count === i + 1 &&
                equal(o.output, {
                  target_id: e.payload.targetId,
                  abstain: e.payload.abstain,
                  ...(type === "vote_cast" ? { weight: e.payload.weight } : {}),
                }),
            ),
          );
    }
  for (const cp of r.checkpoints) {
    const s = snapshots.get(cp.eventCount),
      a: any = cp.animalDream;
    check(s && a);
    let expectedFox = s.fox,
      expectedPuffer = s.puffer,
      expectedEffect = s.effect;
    const expectedNight = structuredClone(s.night),
      expectedUnit = structuredClone(s.unit);
    if (!cp.complete) {
      for (const d of r.decisions.slice(0, cp.decisionCount ?? 0)) {
        const c = tool(d);
        if (!c || d.settleOrder === undefined) continue;
        if (c.name === "fox_distract" && !expectedFox.history.some((h: any) => h.day === d.day)) {
          check(
            d.actorId === foxId &&
              expectedNight?.day === d.day &&
              expectedNight.requiresFox &&
              d.openedAtEventCount! <= cp.eventCount &&
              expectedFox.usedNight === null &&
              d.day >= 2 &&
              snapshots.get(d.openedAtEventCount!)!.alive.includes(foxId) &&
              Object.keys(c.args).length === 1 &&
              (c.args.target_id === null ||
                snapshots.get(d.openedAtEventCount!)!.alive.includes(c.args.target_id)),
          );
          expectedFox = {
            ...expectedFox,
            usedNight: c.args.target_id === null ? null : d.day,
            history: [...expectedFox.history, { day: d.day, targetId: c.args.target_id }],
          };
          expectedNight.foxPaid = true;
          expectedEffect =
            c.args.target_id === null
              ? null
              : {
                  day: d.day,
                  targetId: c.args.target_id,
                  knifeBlocked: wolfIds.includes(c.args.target_id),
                  beautyBlocked: c.args.target_id === beautyId,
                };
        }
        if (
          c.name === "puffer_retaliate" &&
          !expectedPuffer.history.some((h: any) => h.day === d.day)
        ) {
          check(
            d.actorId === pufferId &&
              expectedUnit?.day === d.day &&
              expectedUnit.puffer !== null &&
              expectedPuffer.usedDay === null &&
              snapshots.get(d.openedAtEventCount!)!.alive.includes(pufferId) &&
              Object.keys(c.args).length === 1 &&
              typeof c.args.activate === "boolean",
          );
          const targets = expectedUnit.puffer.targetIds;
          expectedPuffer = {
            ...expectedPuffer,
            usedDay: c.args.activate ? d.day : null,
            history: [
              ...expectedPuffer.history,
              { day: d.day, activate: c.args.activate, targetIds: targets },
            ],
          };
          expectedUnit.puffer = {
            targetIds: targets,
            paid: true,
            activated: c.args.activate,
            closed: true,
          };
        }
      }
      if (expectedNight) expectedNight.status = "aborted";
      if (expectedUnit && expectedUnit.status !== "closed") expectedUnit.status = "aborted";
      if (expectedUnit?.puffer) expectedUnit.puffer.closed = true;
    }
    if (cp.cycle > 0)
      check(
        equal(a.night, expectedNight) &&
          equal(a.unit, expectedUnit) &&
          equal(a.effect, expectedEffect) &&
          a.beautyLinkBlockedDay === s.blockedDay &&
          a.stopped === !cp.complete,
      );
    check(
      equal(a.policies, {
        skippedVotePolicy: board.whiteCat!.skippedVotePolicy,
        ballotPolicy: board.pufferfish!.ballotPolicy,
      }),
    );
    check(
      s &&
        a &&
        a.foxId === foxId &&
        a.catId === catId &&
        a.pufferId === pufferId &&
        equal(a.fox, expectedFox) &&
        equal(a.puffer, expectedPuffer) &&
        equal(a.cat, s.cat) &&
        a.completedUnits === s.completed,
    );
    check(
      cp.operationCount !== undefined &&
        cp.settlementCount !== undefined &&
        cp.decisionCount !== undefined,
    );
    check(
      cp.decisionCount ===
        (cp.cycle === 0
          ? 0
          : r.decisions.filter((d) => d.openedAtEventCount! <= cp.eventCount).length),
    );
    check(
      cp.settlementCount ===
        r.decisions.slice(0, cp.decisionCount).filter((d) => d.outcome.kind !== "pending").length,
    );
    if (r.finalized)
      check(
        cp.operationCount ===
          r.operations.filter((o) => o.event_count !== undefined && o.event_count <= cp.eventCount)
            .length,
      );
    if (cp.complete) {
      const ended = s.result !== null,
        nextDay = cp.cycle > 0 && !ended ? cp.cycle + 1 : s.day,
        nextPhase =
          cp.cycle > 0 && !ended && s.unit?.day === s.day && s.unit.kind === "skipped_day"
            ? "night"
            : s.phase;
      const expectedSnapshot = {
        day: ended ? s.result.decidedAt.day : nextDay,
        phase: ended ? "game_over" : nextPhase,
        gameOver: ended,
        result: s.result,
      };
      check(equal(cp.snapshot, expectedSnapshot));
    }
    if (!cp.complete)
      check(
        equal(cp.snapshot, {
          day: s.day,
          phase: s.phase,
          gameOver: s.result !== null,
          result: s.result,
        }),
      );
    for (const p of cp.players) {
      check(
        equal(p.badge, s.badges.get(p.id)) &&
          equal(p.vote, { weight: s.badges.get(p.id)!.isSheriff ? 1.5 : 1, canVote: true }),
      );
      check(
        p.seat === p.id &&
          equal(p.victory, { affiliations: [{ kind: "faction", faction: p.camp }] }),
      );
      const original = roster.get(p.id);
      check(
        original &&
          p.name === original.name &&
          p.role === original.role &&
          p.camp === original.camp,
      );
    }
    if (cp.cycle === 0)
      check(
        a.night === null &&
          a.unit === null &&
          a.effect === null &&
          a.stopped === false &&
          a.beautyLinkBlockedDay === null &&
          a.completedUnits === 0 &&
          cp.decisionCount === 0 &&
          cp.settlementCount === 0 &&
          cp.operationCount === 0,
      );
    check(
      equal(
        cp.players.filter((p) => p.alive).map((p) => p.id),
        s.alive.filter((id) => !s.publicDead.includes(id)),
      ),
    );
    if (cp.complete) {
      check(!a.stopped);
      if (cp.cycle > 0) check(opened.has(cp.cycle));
    }
    check(equal(cp.players.find((p) => p.id === roleId("bear"))!.privateState, { bear: s.bear }));
    const beautyStock = structuredClone(s.beauty);
    if (expectedEffect?.beautyBlocked) beautyStock.targetId = null;
    check(
      equal(cp.players.find((p) => p.id === beautyId)!.privateState, { wolf_beauty: beautyStock }),
    );
    for (const [id, key, state] of [
      [foxId, "foxCub", expectedFox],
      [catId, "whiteCat", s.cat],
      [pufferId, "pufferfish", expectedPuffer],
    ] as const)
      check(equal(cp.players.find((p) => p.id === id)?.privateState[key], state));
  }
  for (const d of r.decisions) {
    check(
      d.openedAtEventCount !== undefined &&
        d.openedAtEventCount <= r.events.length &&
        d.actorId === d.request.actorId &&
        d.day === d.request.context.day &&
        d.stage === d.request.context.stage,
    );
    if (d.stage === "fox_distract")
      check(
        opened.has(d.day) &&
          r.events
            .slice(0, d.openedAtEventCount)
            .some((e) => e.type === "animal_night_opened" && e.payload.day === d.day) &&
          d.actorId === foxId &&
          d.day >= 2 &&
          equal(d.request.allowedTools, ["fox_distract"]) &&
          equal(d.request.context.fox_candidates, snapshots.get(d.openedAtEventCount)!.alive) &&
          d.request.context.allow_fallback === false,
      );
    if (d.stage === "exile_pk_vote") {
      const prefix = r.events.slice(0, d.openedAtEventCount),
        pk = [...prefix].reverse().find((e) => e.type === "exile_pk_started");
      check(
        pk &&
          equal(d.request.context.exile_candidates, pk.payload.candidates) &&
          !(pk.payload.candidates as number[]).includes(d.actorId) &&
          d.request.context.round === 2,
      );
    }
    if (d.stage === "puffer_reaction")
      check(
        d.actorId === pufferId &&
          equal(d.request.allowedTools, ["puffer_retaliate"]) &&
          d.request.context.allow_fallback === false,
      );
    const feed = d.request.context.visible_events;
    check(equal(feed, animalFeedAt(r, d.openedAtEventCount!, d.actorId)));
    check(feed.every((v, i) => v.seq === i + 1));
    for (const v of feed.filter((v) => animal(v.type))) {
      check(
        ![
          "animal_night_opened",
          "animal_fox_effect",
          "animal_puffer_targets",
          "animal_wave_prepared",
          "animal_wave_committed",
          "animal_cat_expiry_prepared",
          "animal_unit_completed",
        ].includes(v.type),
      );
      check(
        ["animal_cat_revealed", "animal_puffer_revealed"].includes(v.type) ||
          v.payload.actorId === d.actorId,
      );
      check(
        r.events
          .slice(0, d.openedAtEventCount)
          .some((e) => e.type === v.type && equal(e.payload, v.payload)),
      );
    }
  }
}

/**
 * 负责独立核对光蚀归档的请求资格和观察者证据。输入为原席位、归档决定与夜账本；
 * 输出为原一致性结果或明确拒绝，事件／状态重建与请求证据分开验收。
 * 增量记录只从上一 checkpoint 推导尚未归档的夜前缀，不读取 live World 或重开资源。
 * 不创建运行租约、选择实际行动或改变截止时间；失败仅拒绝归档，不改变已付资源或关闭／重开真实窗口。
 */
import { radiantNightRequestPrefix } from "./night-request-prefix";
import { Camp, Phase, Role } from "../../../core/domain/identity";
import type { RecordedDecision, RecordedGameEvent, ReproductionRecord } from "../../../recording/reproduction";
import {
  radiantCheck as check,
  radiantEqual as equal,
  radiantBorrow,
  type RadiantAbility,
  type RadiantNightEvidence,
} from "./validate";
import {
  RADIANT_ECLIPSE_EVENT_TYPES,
  readRadiantEclipseFact,
  radiantEclipseAudience,
} from "@ai-werewolf-arena/game-contract/facts/radiant-eclipse";

const stageTools: Record<string, string[]> = {
  eclipse_swallow: ["swallow_skill"],
  radiant_shelter: ["cast_shelter"],
  dreamer: ["dream"],
  witch: ["use_potion"],
  seer: ["check_identity"],
  wolf_discussion: ["speak_to_wolves"],
  wolf_vote: ["kill_vote"],
  sheriff_nomination: ["run_for_sheriff"],
  sheriff_withdraw: ["run_for_sheriff"],
  sheriff_vote: ["vote_for_sheriff"],
  sheriff_pk_vote: ["vote_for_sheriff"],
  sheriff_speech: ["speak"],
  sheriff_campaign_speech: ["speak"],
  sheriff_pk_speech: ["speak"],
  sheriff_choose_direction: ["choose_direction"],
  sheriff_badge_choice: ["choose_badge_successor"],
  day_speech: ["speak"],
  last_words: ["speak"],
  voting: ["vote"],
  exile_pk_vote: ["vote"],
  exile_pk_speech: ["speak"],
  on_pre_election: ["self_destruct"],
  on_pre_vote: ["self_destruct"],
};
const stageKinds: Record<string, RadiantAbility["kind"]> = {
  radiant_shelter: "shelter",
  dreamer: "dream",
  witch: "potion",
  seer: "seer_check",
};
const publicEvents = new Set([
  "phase_changed",
  "day_speech",
  "night_resolved",
  "vote_summary",
  "voted_out",
  "game_over",
  "wolf_self_destruct",
  "last_words_granted",
  "last_words_spoken",
  "sheriff_nomination_summary",
  "sheriff_withdraw_summary",
  "sheriff_candidates_finalized",
  "sheriff_pk_started",
  "exile_pk_started",
  "sheriff_vote_summary",
  "sheriff_badge_transferred",
  "sheriff_badge_destroyed",
  "sheriff_direction_chosen",
]);
const actorEvents = new Set([
  "ability_changed",
  "seer_checked",
  "dream_applied",
  "witch_potion_used",
  "witch_potion_skipped",
]);
const packEvents = new Set([
  "wolf_tactical_order",
  "wolf_discussion",
  "wolf_discussion_ended",
  "wolf_kill_vote_cast",
]);
function project(e: RecordedGameEvent, actor: number): Record<string, unknown> | null {
  if ((RADIANT_ECLIPSE_EVENT_TYPES as readonly string[]).includes(e.type)) {
    const fact = readRadiantEclipseFact(e.type, e.payload);
    return fact && radiantEclipseAudience(e.type, fact).includes(actor) ? { ...fact } : null;
  }
  if (packEvents.has(e.type)) {
    if (!e.audience?.includes(actor)) return null;
    return { ...e.payload };
  }
  if (actorEvents.has(e.type) && e.payload.actorId !== actor) return null;
  if (!publicEvents.has(e.type) && !actorEvents.has(e.type)) return null;
  if (e.type === "ability_changed") {
    const { sourceDisclosed: _secret, ...p } = e.payload;
    return p;
  }
  if (e.type === "vote_summary") {
    const { tally: _derived, ...p } = e.payload;
    return p;
  }
  return { ...e.payload };
}
export function validateRadiantRequests(
  record: ReproductionRecord,
  context: {
    roster: ReadonlyMap<number, ReproductionRecord["metadata"]["players"][number]>;
    alive: ReadonlySet<number>;
    nights: ReadonlyMap<number, RadiantNightEvidence>;
    maid: number;
    count: number;
    seer: number;
    witch: number;
    dreamer: number;
  },
): void {
  const { roster, nights, maid } = context,
    last = record.checkpoints.at(-1)!;
  const inferred = new Map<
    number,
    {
      start: number[];
      before: Map<number, RadiantAbility | undefined>;
      previousSwallow: { day: number; targetId: number | null } | undefined;
    }
  >();
  const info = (day: number) => {
    const n = nights.get(day);
    if (n) return n;
    let value = inferred.get(day);
    if (value) return value;
    // Trace 的增量快照仍保留上一 checkpoint；尚未形成新 checkpoint 的请求只能
    // 从该历史前缀推导，不拿未发表的最终库存回填，也不声称请求已经完成。
    check(!record.finalized && day === last.snapshot.day);
    const before = new Map(
      last.players.map((p) => [
        p.id,
        structuredClone(
          Object.values((p.privateState.abilities ?? {}) as Record<string, RadiantAbility>).find(
            (a) => a.source.kind === "native",
          ),
        ),
      ]),
    );
    for (const a of before.values())
      if (a?.kind === "potion")
        Object.assign(a.state, {
          healUsedThisNight: false,
          poisonUsedThisNight: false,
          canSelfHeal: false,
        });
    const history = (
      last.players.find((p) => p.id === maid)!.privateState.eclipse as {
        history: Array<{ day: number; targetId: number | null }>;
      }
    ).history;
    value = {
      start: last.players.filter((p) => p.alive).map((p) => p.id),
      before,
      previousSwallow: history.at(-1),
    };
    inferred.set(day, value);
    return value;
  };
  const swallow = (day: number) => {
    const n = info(day),
      ds = record.decisions.filter(
        (d) => d.day === day && d.stage === "eclipse_swallow" && d.actorId === maid,
      ),
      d = ds[0];
    const a = d?.outcome.kind === "action" ? d.outcome.action : null;
    const target = a?.name === "swallow_skill" ? a.args.target_id : null;
    const legal =
      !!d &&
      d.settleOrder !== undefined &&
      a?.name === "swallow_skill" &&
      day >= 2 &&
      n.start.includes(maid) &&
      (target === null ||
        (n.start.includes(target) &&
          roster.get(target)!.camp === Camp.Good &&
          !(n.previousSwallow?.day === day - 1 && n.previousSwallow.targetId === target)));
    const original = legal && target !== null ? n.before.get(target) : undefined;
    return {
      d,
      legal,
      target,
      borrowed: original ? radiantBorrow(original, target!, day) : undefined,
    };
  };
  const settled = record.decisions
    .filter((d) => d.settleOrder !== undefined)
    .map((d) => d.settleOrder!)
    .sort((a, b) => a - b);
  check(settled.every((value, index) => value === index + 1));
  for (const d of record.decisions)
    check(
      d.settleOrder === undefined
        ? d.outcome.kind === "pending"
        : d.outcome.kind !== "pending" && d.openedAfterSettlement < d.settleOrder,
    );
  const prefixes = new Map(
    [
      ...new Set(record.decisions.filter((d) => d.request.phase === Phase.Night).map((d) => d.day)),
    ].map((day) => [day, radiantNightRequestPrefix(record, day, info(day), roster)]),
  );
  const speechCounts = new Map<string, number>();
  const exileRounds = new Map<number, number>();
  const release = (e: RecordedGameEvent, day: number) => {
    const n = prefixes
      .get(day)
      ?.find((f) => f.event.type === e.type && equal(f.event.payload, e.payload));
    if (n) return n.release;
    const max = (rows: RecordedDecision[]) =>
      Math.max(0, ...rows.map((d) => d.settleOrder ?? Number.MAX_SAFE_INTEGER));
    const night = record.decisions.filter((d) => d.day === day && d.request.phase === Phase.Night);
    if (e.type === "phase_changed")
      return e.payload.phase === Phase.Night
        ? max(record.decisions.filter((d) => d.day < Number(e.payload.day)))
        : e.payload.phase === Phase.Day
          ? max(night)
          : e.payload.phase === Phase.Voting
            ? max(record.decisions.filter((d) => d.day === day && d.request.phase === Phase.Day))
            : max(record.decisions.filter((d) => d.day <= day));
    if (e.type === "night_resolved")
      return Math.max(
        max(night),
        day === 1
          ? max(
              record.decisions.filter(
                (d) =>
                  d.day === 1 &&
                  [
                    "sheriff_nomination",
                    "sheriff_withdraw",
                    "sheriff_campaign_speech",
                    "sheriff_vote",
                    "sheriff_pk_vote",
                    "sheriff_pk_speech",
                    "on_pre_election",
                  ].includes(d.stage),
              ),
            )
          : 0,
      );
    if (e.type === "game_over") return max(record.decisions.filter((d) => d.day <= day));
    if (e.type === "eclipse_native_restored" || e.type === "eclipse_lease_closed")
      return max(night);
    const stages: Record<string, string[]> = {
      day_speech: ["day_speech", "sheriff_campaign_speech", "sheriff_pk_speech", "exile_pk_speech"],
      last_words_spoken: ["last_words"],
      sheriff_badge_transferred: ["sheriff_badge_choice"],
      sheriff_badge_destroyed: ["sheriff_badge_choice"],
      sheriff_direction_chosen: ["sheriff_choose_direction"],
      vote_summary: ["voting", "exile_pk_vote"],
      voted_out: ["voting", "exile_pk_vote"],
      sheriff_nomination_summary: ["sheriff_nomination"],
      sheriff_withdraw_summary: ["sheriff_nomination", "sheriff_withdraw"],
      sheriff_candidates_finalized: ["sheriff_nomination", "sheriff_withdraw"],
      sheriff_pk_started: ["sheriff_vote"],
      sheriff_vote_summary: [
        "sheriff_nomination",
        "sheriff_withdraw",
        "sheriff_vote",
        "sheriff_pk_vote",
      ],
    };
    if (e.type === "day_speech") {
      const key = day + "/" + e.payload.actorId,
        index = speechCounts.get(key) ?? 0;
      const candidates = record.decisions
        .filter(
          (d) =>
            d.day === day &&
            d.actorId === e.payload.actorId &&
            stages.day_speech!.includes(d.stage) &&
            d.outcome.kind === "action" &&
            d.outcome.action?.name === "speak",
        )
        .sort((a, b) => a.settleOrder! - b.settleOrder!);
      const selected = candidates[index];
      speechCounts.set(key, index + 1);
      check(
        selected?.outcome.kind === "action" &&
          selected.outcome.action?.name === "speak" &&
          selected.outcome.action.args.text.trim().length > 0,
      );
      check(
        selected.outcome.action.args.text
          .replace(/^(\s*\[(上帝|法官|系统|God|Judge|System)\]\s*)+/gi, "")
          .trim() === e.payload.text,
      );
      return selected.settleOrder!;
    }
    if (e.type === "sheriff_vote_summary")
      return max(
        record.decisions.filter(
          (d) =>
            d.day === day &&
            ((e.payload.round ?? 1) === 2
              ? d.stage === "sheriff_pk_vote"
              : ["sheriff_nomination", "sheriff_withdraw", "sheriff_vote"].includes(d.stage)),
        ),
      );
    if (e.type === "vote_summary" || e.type === "voted_out" || e.type === "exile_pk_started") {
      const round =
        e.type === "vote_summary" ? Number(e.payload.round ?? 1) : (exileRounds.get(day) ?? 1);
      const boundary = max(
        record.decisions.filter(
          (d) => d.day === day && d.stage === (round === 2 ? "exile_pk_vote" : "voting"),
        ),
      );
      if (e.type === "exile_pk_started") exileRounds.set(day, 2);
      return boundary;
    }
    const relevant = stages[e.type];
    if (relevant)
      return max(
        record.decisions.filter(
          (d) =>
            d.day === day &&
            relevant.includes(d.stage) &&
            (typeof (
              e.payload.actorId ??
              e.payload.playerId ??
              e.payload.fromId ??
              e.payload.sheriffId
            ) !== "number" ||
              d.actorId ===
                (e.payload.actorId ??
                  e.payload.playerId ??
                  e.payload.fromId ??
                  e.payload.sheriffId)),
        ),
      );
    if (e.type === "last_words_granted")
      return Math.max(
        max(night),
        day === 1
          ? max(
              record.decisions.filter(
                (d) =>
                  d.day === 1 &&
                  [
                    "sheriff_nomination",
                    "sheriff_withdraw",
                    "sheriff_campaign_speech",
                    "sheriff_vote",
                    "sheriff_pk_vote",
                    "sheriff_pk_speech",
                    "on_pre_election",
                  ].includes(d.stage),
              ),
            )
          : 0,
        e.payload.phase === Phase.Voting
          ? max(
              record.decisions.filter(
                (d) => d.day === day && ["voting", "exile_pk_vote"].includes(d.stage),
              ),
            )
          : 0,
      );
    if (e.type === "wolf_self_destruct")
      return max(record.decisions.filter((d) => d.day === day && d.stage === e.payload.window));
    return Number.MAX_SAFE_INTEGER;
  };
  const published = new Map(
    [...roster.keys()].map((id) => [
      id,
      [] as Array<{ type: string; payload: Record<string, unknown>; release: number; day: number }>,
    ]),
  );
  let eventDay = 1;
  for (const e of record.events) {
    if (e.type === "phase_changed") eventDay = Number(e.payload.day);
    const boundary = release(e, eventDay);
    for (const id of roster.keys()) {
      const p = project(e, id);
      if (p)
        published.get(id)!.push({ type: e.type, payload: p, release: boundary, day: eventDay });
    }
  }
  const used = new Set<string>();
  for (const d of record.decisions) {
    const key = `${d.actorId}/${d.day}/${d.stage}/${d.turn}`;
    check(!used.has(key));
    used.add(key);
    if (d.outcome.kind === "action" && d.outcome.action?.name === "speak")
      check(
        Object.keys(d.outcome.action.args).length === 1 &&
          Object.hasOwn(d.outcome.action.args, "text"),
      );
    check(
      roster.has(d.actorId) &&
        d.request.actorId === d.actorId &&
        d.request.context.day === d.day &&
        d.request.context.stage === d.stage &&
        stageTools[d.stage] &&
        equal(d.request.allowedTools, stageTools[d.stage]),
    );
    const ctx = d.request.context,
      isNight = [
        "eclipse_swallow",
        "radiant_shelter",
        "dreamer",
        "witch",
        "seer",
        "wolf_discussion",
        "wolf_vote",
      ].includes(d.stage);
    if (isNight) {
      const allowed = [
        "day",
        "stage",
        "visible_events",
        "turn_constraints",
        "allow_fallback",
        "action_failure_policy",
        ...(d.stage === "eclipse_swallow" ? ["swallow_candidates"] : []),
        ...(d.stage === "radiant_shelter" ? ["ability_id", "shelter_candidates"] : []),
        ...(["witch", "seer", "dreamer"].includes(d.stage) ? ["ability_id"] : []),
        ...(d.stage === "witch" ? ["wolf_target"] : []),
        ...(d.stage === "wolf_discussion" ? ["round", "max_rounds"] : []),
      ];
      check(Object.keys(ctx).every((key) => allowed.includes(key)));
      const n = info(d.day),
        s = swallow(d.day),
        kind = stageKinds[d.stage];
      check(
        d.request.phase === Phase.Night &&
          n.start.includes(d.actorId) &&
          ctx.allow_fallback === false &&
          ctx.action_failure_policy === "error",
      );
      check(
        ctx.turn_constraints.min_valid_actions === 1 &&
          ctx.turn_constraints.max_valid_actions === 1 &&
          equal(ctx.turn_constraints.required_any_tools, d.request.allowedTools),
      );
      if (d.stage === "eclipse_swallow") {
        check(d.day >= 2 && d.actorId === maid && d.turn === 1 && ctx.ability_id === undefined);
        const candidates = n.start.filter(
          (id) =>
            roster.get(id)!.camp === Camp.Good &&
            !(n.previousSwallow?.day === d.day - 1 && n.previousSwallow.targetId === id),
        );
        check(equal(ctx.swallow_candidates, candidates) && ctx.shelter_candidates === undefined);
      } else if (kind) {
        const a = d.actorId === maid ? s.borrowed : n.before.get(d.actorId);
        check(
          a &&
            a.kind === kind &&
            d.day >= a.startsOnDay &&
            ctx.ability_id === a.id &&
            d.turn === 1 &&
            (d.actorId === maid
              ? s.legal && s.d!.settleOrder! <= d.openedAfterSettlement
              : !s.legal || s.target !== d.actorId),
        );
        if (kind === "shelter") {
          const ids = n.start.filter(
            (id) =>
              id !== d.actorId && !(a.state.lastDay === d.day - 1 && a.state.lastTarget === id),
          );
          check(equal(ctx.shelter_candidates, ids));
        }
        if (kind === "potion") {
          check(d.actorId !== maid || a.state.heal > 0 || a.state.poison > 0);
          if (a.state.heal > 0) {
            const votes = record.decisions.filter(
                (x) =>
                  x.day === d.day &&
                  x.stage === "wolf_vote" &&
                  x.settleOrder !== undefined &&
                  x.settleOrder <= d.openedAfterSettlement,
              ),
              tally = new Map<number, number>();
            for (const v of votes) {
              const a = v.outcome.kind === "action" ? v.outcome.action : null;
              if (a?.name === "kill_vote" && !a.args.abstain && a.args.target_id !== null)
                tally.set(a.args.target_id, (tally.get(a.args.target_id) ?? 0) + 1);
            }
            const knife = [...tally].sort(([a, x], [b, y]) => y - x || a - b)[0]?.[0] ?? null;
            check(ctx.wolf_target === knife);
          } else check(!Object.hasOwn(ctx, "wolf_target"));
        }
      } else {
        const wolves = n.start.filter((id) => roster.get(id)!.role === Role.Wolf),
          holders = wolves.length ? wolves : n.start.includes(maid) ? [maid] : [];
        check(
          ctx.ability_id === undefined &&
            (d.stage === "wolf_discussion" ? wolves : holders).includes(d.actorId),
        );
        if (d.stage === "wolf_discussion") {
          check(d.turn <= 3 && ctx.round === d.turn && ctx.max_rounds === 3);
          for (const prior of record.decisions.filter(
            (x) =>
              x.day === d.day && x.stage === d.stage && x.actorId === d.actorId && x.turn < d.turn,
          )) {
            const a = prior.outcome.kind === "action" ? prior.outcome.action : null;
            check(
              a?.name === "speak_to_wolves" &&
                a.args.end_chat === false &&
                prior.settleOrder! <= d.openedAfterSettlement,
            );
          }
        } else check(d.turn === 1);
      }
      for (const name of ["shelter_candidates", "swallow_candidates"] as const)
        if (Object.hasOwn(ctx, name))
          check(
            d.stage === (name === "shelter_candidates" ? "radiant_shelter" : "eclipse_swallow"),
          );
    } else {
      check(
        ctx.ability_id === undefined &&
          !Object.hasOwn(ctx, "shelter_candidates") &&
          !Object.hasOwn(ctx, "swallow_candidates"),
      );
      if (d.stage === "on_pre_election" || d.stage === "on_pre_vote")
        check(
          roster.get(d.actorId)!.role === Role.Wolf &&
            d.request.phase === (d.stage === "on_pre_vote" ? Phase.Voting : Phase.Day),
        );
    }
    const visible = ctx.visible_events;
    check(visible.every((v, i) => v.seq === i + 1));
    const sources = published.get(d.actorId)!.filter((v) => v.release <= d.openedAfterSettlement);
    let expected = sources.map(({ release: _release, day: _day, ...v }) => v);
    if (!record.finalized) {
      const allPublished = published.get(d.actorId)!.filter((v) => v.day === d.day);
      const extra = (prefixes.get(d.day) ?? [])
        .filter((f) => f.release <= d.openedAfterSettlement)
        .flatMap((f) => {
          const p = project({ ...f.event, timestamp: 0 }, d.actorId);
          return p && !allPublished.some((v) => v.type === f.event.type && equal(v.payload, p))
            ? [{ type: f.event.type, payload: p }]
            : [];
        });
      expected = [...expected, ...extra];
    }
    check(
      equal(
        visible.map(({ seq: _seq, ...v }) => v),
        expected,
      ),
    );
    const latestPhase = [...visible].reverse().find((v) => v.type === "phase_changed");
    check(
      !!latestPhase &&
        latestPhase.payload.phase === d.request.phase &&
        latestPhase.payload.day === d.day,
    );
  }
}

